import {exercises,muscles,equipmentNames,available,dayWorkout,planEditKey} from './data.js';
import {weeklyStats,sessionSequence,measureUnit} from './training-core.js';
import {currentLocale,translateText} from './i18n.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const weekdays=['Pazartesi','Salı','Çarşamba','Perşembe','Cuma','Cumartesi','Pazar'];
export function todayRoutines(s){const today=(new Date().getDay()+6)%7,list=(s.routines||[]).filter(r=>r.day===today);return list.length?`<section class="studio-panel routine-today"><div class="section-heading"><h2>Bugünkü özel programların</h2><span class="mini-pill">${weekdays[today]}</span></div>${list.map(r=>`<button class="exercise-row" data-feature="routine-preview" data-id="${r.id}"><span><strong data-i18n-ignore>${esc(r.name)}</strong><small>${r.items.length} hareket · Haftalık programın</small></span><span>↗</span></button>`).join('')}</section>`:'';}
export const heatColor=n=>n>=8?'#ff9b60':n>=4?'#bda2ff':n>0?'#69d8be':'#53596a';
export function heatCounts(s){return weeklyStats(s.history,exercises).counts;}
export function heatControls(s,heat,k){const counts=heatCounts(s);return `<section class="feature-banner"><div><span class="eyebrow">BU HAFTAKİ ÇALIŞMAN</span><h3>${heat?(counts[k]||0)+' set · '+muscles[k].name:'Anatomiden antrenmanına'}</h3><p>Hafta pazartesi başlar. Ana ve yardımcı kas eşleşmeleri dahildir; toparlanma veya kas büyümesi ölçümü değildir.</p></div><button class="secondary" data-action="heat-toggle" aria-pressed="${heat}">${heat?'Anatomi renklerine dön':'Haftalık çalışma haritası'}</button>${heat?'<div class="heat-legend"><span style="--heat:#53596a">0 set</span><span style="--heat:#69d8be">1–3 set</span><span style="--heat:#bda2ff">4–7 set</span><span style="--heat:#ff9b60">8+ set</span></div>':''}</section>`;}
export function weeklyMarkup(s){const w=weeklyStats(s.history,exercises),range=w.start.toLocaleDateString(currentLocale(),{day:'numeric',month:'long'});return `<section class="studio-panel weekly-report"><div class="section-heading"><div><span class="eyebrow">HAFTALIK ÖZET · ${range}</span><h2>Bu hafta neler değişti?</h2></div><span class="mini-pill">Tamamlanan kayıtlardan</span></div><div class="report-metrics"><div><strong>${w.current.length}</strong><small>seans</small></div><div><strong>${w.sets}</strong><small>kuvvet seti</small></div><div><strong>${w.minutes}</strong><small>dakika</small></div></div><p>${!w.current.length?'Bu haftanın ilk seansından sonra özetin oluşacak.':!w.before.length?'Önceki haftada kaydın yok. Bu hafta karşılaştırmaların için başlangıç olacak.':w.delta===0?'Geçen haftayla aynı sayıda seans tamamladın.':`Geçen haftanın tamamına göre ${Math.abs(w.delta)} seans ${w.delta>0?'fazla':'az'} tamamladın. Bu hafta henüz bitmemiş olabilir.`}</p>${w.gains.slice(0,3).map(g=>`<div class="record-row"><span>${esc(g.name)}</span><strong>+${g.delta} tekrar <small>${g.load!=null?g.load+' kg ile':'yüksüz kayıtta'}</small></strong></div>`).join('')}<small>Aynı harekette, aynı girilmiş yükteki en yüksek set tekrarı karşılaştırılır. Eksik set kayıtları kas haritasına yansımaz.</small><button class="text-button" data-feature="report-atlas">Kas haritamı aç ↗</button></section>`;}
function ensure(s){if(!Array.isArray(s.gymProfiles))s.gymProfiles=[{id:'home',name:'Evim',place:'home',equipment:s.place==='home'?[...s.equipment]:[]},{id:'gym',name:'Spor salonum',place:'gym',equipment:s.place==='gym'?[...s.equipment]:[]},{id:'travel',name:'Seyahat',place:'home',equipment:[]}];if(!s.activeGym)s.activeGym=s.place==='gym'?'gym':'home';if(!Array.isArray(s.routines))s.routines=[];}
export function syncProfile(s){ensure(s);const p=s.gymProfiles.find(x=>x.id===s.activeGym);if(p){p.place=s.place;p.equipment=[...s.equipment];}}
export function profileBar(s){ensure(s);return `<div class="profile-switch"><span>ANTRENMAN ALANIN</span>${s.gymProfiles.map(p=>`<button data-feature="profile-switch" data-id="${esc(p.id)}" aria-pressed="${s.activeGym===p.id}">${esc(p.name)}</button>`).join('')}<button data-feature="profiles">Düzenle ⚙</button></div>`;}
export function routinePanel(s){ensure(s);return `<section class="studio-panel routine-section"><div class="section-heading"><div><span class="eyebrow">PROGRAM STÜDYOSU</span><h2>Kendi haftanı tasarla.</h2></div><button class="primary" data-feature="routine-new">＋ Program oluştur</button></div><p class="muted">Hareketlerini sırala, setlerini belirle ve istersen iki hareketi süperset olarak eşleştir.</p>${s.routines.length?`<div class="routine-grid">${s.routines.map(r=>`<article class="routine-card"><span class="eyebrow">${weekdays[r.day]||'Gün seçilmedi'}</span><h3 data-i18n-ignore>${esc(r.name)}</h3><p>${r.items.length} hareket · ${r.items.reduce((n,x)=>n+x.sets,0)} hedef set/tur</p><div class="routine-actions"><button class="secondary" data-feature="routine-edit" data-id="${r.id}">Düzenle</button><button class="primary" data-feature="routine-preview" data-id="${r.id}">Seansı aç ↗</button></div></article>`).join('')}</div>`:'<div class="empty">İlk programını oluştur. Kaydettiğin programı her hafta yeniden kullanabilirsin.</div>'}<div class="adaptive-setting"><label><input type="checkbox" id="adaptive-setting" ${s.adaptive!==false?'checked':''}> Hazır aylık planı performansıma göre uyarla</label><small>Son seans zorsa bir set azaltılır. Kolay seanslarda önce tekrar, yeterli kayıt olduğunda küçük yük artışı önerilir. Özel programlar kendi hedeflerini korur.</small></div></section>`;}
export function feedbackMarkup(index,value){return `<section class="feedback-box"><h3>Bu seans nasıl geçti?</h3><p>Bir sonraki hazır plan önerisini şekillendirir. Ağrı yaşadıysan zorlamayı bırak; bunu gelişim işareti olarak değerlendirme.</p><div class="energy-options">${[['easy','Kolay'],['balanced','Dengeli'],['hard','Zor']].map(([v,label])=>`<button data-feature="feedback" data-id="${index}" data-value="${v}" aria-pressed="${value===v}">${label}</button>`).join('')}</div></section>`;}
export function initFeatures(ctx){
 let builder=null,profileDraft=null,editingProfile=null,editingPlanDay=null;
 const wrap=html=>ctx.open('<div class="modal-content">'+html+'</div>');
 function builderView(){const s=ctx.state(),allowed=available(s);wrap(ctx.top(editingPlanDay===null?'Program stüdyosu':'Planını kişiselleştir')+`<form id="routine-form">${editingPlanDay!==null?'<p class="editor-context">Bu günün hareketleri dört hafta boyunca güncellenir. Diğer günler aynı kalır.</p>':''}<div class="editor-fields" ${editingPlanDay!==null?'hidden':''}><label>Program adı<input id="routine-name" maxlength="60" required value="${esc(builder.name)}"></label><label>Haftalık gün<select id="routine-day">${weekdays.map((d,i)=>`<option value="${i}" ${builder.day===i?'selected':''}>${d}</option>`).join('')}</select></label></div><div class="builder-summary"><strong>${builder.items.length}</strong><span>hareket</span><small>Set, tekrar ve sırayı sen belirle.</small></div><div class="builder-list">${builder.items.map((item,i)=>{const e=exercises.find(e=>e.id===item.id);return `<div class="builder-item"><div class="builder-title"><b>${i+1}. ${esc(e.name)}</b><div><button type="button" data-feature="move" data-index="${i}" data-value="-1" aria-label="${esc(e.name)} yukarı" ${i===0?'disabled':''}>↑</button><button type="button" data-feature="move" data-index="${i}" data-value="1" aria-label="${esc(e.name)} aşağı" ${i===builder.items.length-1?'disabled':''}>↓</button><button type="button" data-feature="remove-item" data-index="${i}" aria-label="${esc(e.name)} programdan çıkar">×</button></div></div><div class="editor-fields"><label>Set / tur<input data-edit="sets" data-index="${i}" type="number" min="1" max="6" required value="${item.sets}"></label><label>${measureUnit(e)==='sn'?'Süre hedefi (saniye)':measureUnit(e)==='dk'?'Süre hedefi (dakika)':'Tekrar hedefi'}<input data-edit="reps" data-index="${i}" type="number" min="1" max="120" required value="${item.reps}"></label></div>${i<builder.items.length-1?`<label class="pair-control"><input data-edit="pairNext" data-index="${i}" type="checkbox" ${item.pairNext?'checked':''} ${i>0&&builder.items[i-1].pairNext?'disabled':''}> Sonraki hareketle süperset</label>`:''}${!allowed.some(a=>a.id===e.id)?'<small class="missing-equipment">Bu alanda gerekli ekipman seçili değil.</small>':''}</div>`;}).join('')}</div><label class="add-exercise-label">Egzersiz ara<input id="builder-search" type="search" placeholder="Egzersiz ara" autocomplete="off"></label><label class="add-exercise-label">Hareket ekle<select id="routine-exercise"><option value="">Ekipmanıma uygun hareket seç…</option>${allowed.filter(e=>!builder.items.some(x=>x.id===e.id)).map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('')}</select></label><button type="button" class="secondary full" data-feature="add-item">＋ Hareketi ekle</button><p class="muted">Süpersette iki hareket arasında planlı dinlenme yoktur; tur sonunda dinlenirsin. İhtiyaç duyduğunda ara ver.</p><button class="primary full" type="submit">${editingPlanDay===null?'Programı kaydet ✓':'Değişiklikleri plana uygula'}</button><p id="builder-error" role="status"></p></form>`);}
 function preview(id){const r=ctx.state().routines.find(r=>r.id===id);if(!r)return;const allowed=available(ctx.state()),missing=r.items.filter(x=>!allowed.some(e=>e.id===x.id));wrap(ctx.top(esc(r.name))+`<span class="eyebrow">${weekdays[r.day]} · ÖZEL PROGRAM</span>${r.items.map((item,i)=>`<div class="exercise-row"><span class="number">${i+1}</span><span><strong>${esc(exercises.find(e=>e.id===item.id).name)}</strong><small>${item.sets} set/tur · ${item.reps} hedef ${item.pairNext?'· Süperset başlangıcı':''}</small></span></div>`).join('')}${missing.length?'<div class="tip">Bu programın bazı ekipmanları mevcut alanında seçili değil. Programı düzenle veya antrenman alanını değiştir.</div>':`<button class="primary full" data-feature="routine-start" data-id="${id}">Bu programla başla ↗</button>`}`);}
 function profiles(){ensure(ctx.state());wrap(ctx.top('Antrenman alanların')+'<p class="muted">Her alanın ekipman listesi ayrı saklanır. Alan değiştirmek aylık takvimini sıfırlamaz.</p>'+ctx.state().gymProfiles.map(p=>`<div class="profile-edit-row"><div><h3>${esc(p.name)}</h3><small>${p.equipment.length} ekipman · ${p.place==='gym'?'Salon':'Ev / seyahat'}</small></div><button class="secondary" data-feature="profile-edit" data-id="${p.id}">Düzenle</button></div>`).join(''));}
 function profileEditor(id){editingProfile=id;profileDraft=structuredClone(ctx.state().gymProfiles.find(p=>p.id===id));drawProfile();}
 function drawProfile(){wrap(ctx.top('Alanını düzenle')+`<form id="profile-form"><label class="add-exercise-label">Alan adı<input id="profile-name" value="${esc(profileDraft.name)}" required maxlength="30"></label><label class="add-exercise-label">Alan türü<select id="profile-place"><option value="home" ${profileDraft.place==='home'?'selected':''}>Ev / seyahat</option><option value="gym" ${profileDraft.place==='gym'?'selected':''}>Spor salonu</option></select></label><div class="equipment-actions"><button type="button" class="text-button" data-feature="profile-all">Tümünü seç</button><button type="button" class="quiet" data-feature="profile-none">Seçimi temizle</button></div><div class="equipment">${Object.entries(equipmentNames).filter(([k])=>k!=='none').map(([k,label])=>`<label class="check-choice"><input class="profile-equipment" value="${k}" type="checkbox" ${profileDraft.equipment.includes(k)?'checked':''}>${label}</label>`).join('')}</div><button class="primary full" type="submit">Alanı kaydet ✓</button></form>`);}
 document.addEventListener('input',ev=>{const t=ev.target;if(t.id==='builder-search'){const query=t.value.toLocaleLowerCase(currentLocale());document.querySelectorAll('#routine-exercise option').forEach(o=>{o.hidden=!!o.value&&!o.textContent.toLocaleLowerCase(currentLocale()).includes(query);});document.querySelector('#routine-exercise').value='';}if(builder){if(t.id==='routine-name')builder.name=t.value;if(t.id==='routine-day')builder.day=+t.value;if(t.dataset.edit){const item=builder.items[+t.dataset.index];if(item)item[t.dataset.edit]=t.dataset.edit==='pairNext'?t.checked:+t.value;}}if(profileDraft){if(t.id==='profile-name')profileDraft.name=t.value;if(t.id==='profile-place')profileDraft.place=t.value;if(t.classList.contains('profile-equipment'))profileDraft.equipment=[...document.querySelectorAll('.profile-equipment:checked')].map(x=>x.value);}});
 document.addEventListener('change',ev=>{if(ev.target.id==='adaptive-setting'){ctx.state().adaptive=ev.target.checked;ctx.save();ctx.render();}if(ev.target.dataset.edit==='pairNext'){const i=+ev.target.dataset.index;if(builder.items[i].pairNext&&builder.items[i+1])builder.items[i+1].pairNext=false;builderView();}});
 document.addEventListener('submit',ev=>{if(ev.target.id==='routine-form'){ev.preventDefault();if(!ev.target.reportValidity())return;if(!builder.items.length){document.querySelector('#builder-error').textContent='En az bir hareket ekle.';return;}if(editingPlanDay!==null&&ctx.state().activeSession){ctx.toast('Önce kayıtlı seansını tamamla.');return;}builder.name=builder.name.trim();if(!builder.name){document.querySelector('#builder-error').textContent='Bir program adı yaz.';return;}builder.items.at(-1).pairNext=false;const s=ctx.state();if(editingPlanDay!==null){s.planEdits=s.planEdits||{};s.planEdits[planEditKey(s,s.plan,editingPlanDay)]={items:structuredClone(builder.items)};editingPlanDay=null;builder=null;ctx.save();ctx.close();ctx.render();ctx.toast('Planın güncellendi.');return;}const i=s.routines.findIndex(r=>r.id===builder.id);if(i<0)s.routines.push(structuredClone(builder));else s.routines[i]=structuredClone(builder);ctx.save();ctx.close();ctx.render();ctx.toast('Programın kaydedildi.');}if(ev.target.id==='profile-form'){ev.preventDefault();if(!ev.target.reportValidity())return;profileDraft.name=profileDraft.name.trim();if(!profileDraft.name)return;const s=ctx.state(),i=s.gymProfiles.findIndex(p=>p.id===editingProfile);s.gymProfiles[i]=structuredClone(profileDraft);if(s.activeGym===editingProfile){s.place=profileDraft.place;s.equipment=[...profileDraft.equipment];}ctx.save();ctx.close();ctx.render();ctx.toast('Ekipman profilin kaydedildi.');}});
 document.addEventListener('click',ev=>{const b=ev.target.closest('[data-feature]');if(!b)return;const a=b.dataset.feature,id=b.dataset.id,v=b.dataset.value,s=ctx.state();ensure(s);
  if(a==='report-atlas')ctx.heat();
  if(a==='feedback'){const h=s.history[+id];if(h){h.feedback=v;ctx.save();const box=b.closest('.feedback-box');box.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));ctx.toast('Geri bildirimin sonraki hazır plan önerisine işlendi.');}}
  if(a==='profiles')profiles();if(a==='profile-edit')profileEditor(id);
  if(a==='profile-switch'){syncProfile(s);const p=s.gymProfiles.find(p=>p.id===id);s.activeGym=id;s.place=p.place;s.equipment=[...p.equipment];ctx.save();ctx.render();ctx.toast(p.name+' ekipmanları seçildi.');}
  if(a==='profile-all'||a==='profile-none'){profileDraft.equipment=a==='profile-all'?Object.keys(equipmentNames).filter(k=>k!=='none'):[];drawProfile();}
  if(a==='routine-new'){editingPlanDay=null;builder={id:crypto.randomUUID(),name:translateText('Yeni programım'),day:0,items:[]};builderView();}
  if(a==='routine-edit'){editingPlanDay=null;builder=structuredClone(s.routines.find(r=>r.id===id));builderView();}
  if(a==='routine-preview')preview(id);
  if(a==='plan-edit'){if(s.activeSession){ctx.toast('Önce kayıtlı seansını tamamla.');return;}const day=Number(b.dataset.day),w=dayWorkout(s,s.plan,day);if(w.rest)return;editingPlanDay=day;builder={name:w.title,day:0,items:w.exercises.map(e=>({id:e.id,sets:e.sets||w.sets,reps:parseInt(e.reps)||10,pairNext:!!e.pairNext}))};builderView();}
  if(a==='plan-reset'){if(s.activeSession){ctx.toast('Önce kayıtlı seansını tamamla.');return;}if(s.planEdits)delete s.planEdits[planEditKey(s,s.plan,Number(b.dataset.day))];ctx.save();ctx.render();ctx.toast('Hazır hareketler geri yüklendi.');}
  if(a==='add-item'){const id=document.querySelector('#routine-exercise').value;if(id&&available(s).some(e=>e.id===id)&&!builder.items.some(x=>x.id===id)){const e=exercises.find(e=>e.id===id);builder.items.push({id,sets:e.category==='strength'?2:1,reps:parseInt(e.reps)||10,pairNext:false});builderView();}}
  if(a==='move'){const i=+b.dataset.index,j=i+(+v);if(j>=0&&j<builder.items.length){[builder.items[i],builder.items[j]]=[builder.items[j],builder.items[i]];builder.items.forEach(x=>x.pairNext=false);builderView();}}
  if(a==='remove-item'){builder.items.splice(+b.dataset.index,1);builder.items.forEach(x=>x.pairNext=false);builderView();}
  if(a==='routine-start'){const r=s.routines.find(r=>r.id===id);if(!r)return;const allowed=available(s);if(r.items.some(x=>!allowed.some(e=>e.id===x.id))){ctx.toast('Önce programına uygun ekipman alanını seç.');return;}const w={title:r.name,rest:false,week:0,sets:2,minutes:r.items.reduce((n,x)=>n+x.sets*2,0),routineId:r.id,exercises:r.items.map(x=>{const e=exercises.find(e=>e.id===x.id),unit=measureUnit(e)==='sn'?'saniye':measureUnit(e)==='dk'?'dakika':'tekrar';return{...e,sets:x.sets,pairNext:x.pairNext,reps:x.reps+' '+unit};})};w.sequence=sessionSequence(w);ctx.start(-1,w);}
 });
}
